function backupWork():string {$dir=backupRoot().'/.tmp-'.bin2hex(random_bytes(12));if(!mkdir($dir,0700))throw new RuntimeException('Radni prostor kopije nije dostupan.');return $dir;}
function backupClean(string $dir):void {
