function backupQuote(string $name):string {if(!preg_match('/^[a-zA-Z0-9_]+$/D',$name))throw new RuntimeException('Nepodržan naziv tabele.');return '`'.$name.'`';}
function backupSchema(string $table):string {$row=query('SHOW CREATE TABLE '.backupQuote($table))->fetch(PDO::FETCH_NUM);return hash('sha256',preg_replace('/AUTO_INCREMENT=\d+\s*/','',(string)$row[1]));}
function backupPhotoPath(string $path):bool {return (bool)preg_match('~^uploads/(?:[a-zA-Z0-9_-]+\.(?:jpg|jpeg|png|webp)|\.htaccess|\.gitkeep)$~D',$path);}
function backupLock():void {
    $held=[];try{foreach(['webshop_mutations','webshop_backup_operation','webshop_schema_upgrade','webshop_mail_jobs'] as $lock){if((int)query('SELECT GET_LOCK(?,0)',[$lock])->fetchColumn()!==1)throw new RuntimeException('Druga obrada, slanje maila ili nadogradnja je u toku. Pokušajte ponovo kasnije.');$held[]=$lock;}}catch(Throwable $e){foreach(array_reverse($held) as $lock)query('SELECT RELEASE_LOCK(?)',[$lock]);throw $e;}
}
function backupUnlock():void {foreach(['webshop_mail_jobs','webshop_schema_upgrade','webshop_backup_operation','webshop_mutations'] as $lock)query('SELECT RELEASE_LOCK(?)',[$lock]);}
