function backupList():array {$items=[];foreach(glob(backupRoot().'/*.json')?:[] as $path){$m=json_decode((string)file_get_contents($path),true);if(is_array($m)&&isset($m['id'])&&preg_match('/^\d{8}-\d{6}-[a-f0-9]{12}$/D',$m['id'])&&is_file(backupRoot().'/'.$m['id'].'.wsb'))$items[]=$m;}usort($items,static fn($a,$b)=>strcmp($b['id'],$a['id']));return $items;}
