function backupInspect(string $id):array {$data=backupOpen($id);try{$metaPath=backupRoot().'/'.backupId($id).'.json';$meta=json_decode((string)file_get_contents($metaPath),true);$meta['checked_at']=date(DATE_ATOM);file_put_contents($metaPath,json_encode($meta,JSON_THROW_ON_ERROR));audit('backup.verified',null,$id);return $data['manifest'];}finally{backupClean($data['work']);}}
function backupImport(string $temporary):string {
