        if(!$committed){if(is_dir($stage.'/old-uploads')){if(is_dir($uploads)&&!rename($uploads,$stage.'/interrupted-uploads'))throw new RuntimeException('Fajlove nije moguće pripremiti za oporavak.');if(!rename($stage.'/old-uploads',$uploads))throw new RuntimeException('Fotografije nisu oporavljene.');}
